package com.pridesys.ticketing.issue.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
import com.pridesys.ticketing.dto.*; import com.pridesys.ticketing.entity.*; import com.pridesys.ticketing.issue.service.impl.IssueServiceImpl; import com.pridesys.ticketing.repository.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.security.access.AccessDeniedException; import java.util.*;
@ExtendWith(MockitoExtension.class) class IssueServiceTest { @Mock IssueRepository issues; @Mock IssueAuditRepository audits; @Mock ProjectRepository projects; @InjectMocks IssueServiceImpl service;
 @Test void clientUserCannotMoveOthersIssue(){var a=user(2);var i=new IssueEntity("x","d",IssueType.BUG,IssuePriority.HIGH,9,null,3);i.setId(1L);when(issues.findById(1L)).thenReturn(Optional.of(i));when(projects.member(9,2)).thenReturn(true);assertThrows(AccessDeniedException.class,()->service.move(a,1L,IssueStage.DECLINED));}
 @Test void clientUserMayDeclineOwnSubmittedIssue(){var a=user(2);var i=new IssueEntity("x","d",IssueType.BUG,IssuePriority.HIGH,9,null,2);i.setId(1L);when(issues.findById(1L)).thenReturn(Optional.of(i));when(projects.member(9,2)).thenReturn(true);when(issues.save(i)).thenReturn(i);assertEquals(IssueStage.DECLINED,service.move(a,1L,IssueStage.DECLINED).stage());verify(audits).save(any());}
 private UserEntity user(long id){var u=new UserEntity("u@test.com","x",UserRole.CLIENT_USER,"U",1L);u.setId(id);return u;} }
